import{_ as s,l,o as e,c as i,v as t,p as c,x as r,d as n,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Lucas 树","description":"","frontmatter":{"title":"Lucas 树","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lucas-tree.md","filePath":"econ/lucas-tree.md","lastUpdated":1789023840000}'),u={name:"econ/lucas-tree.md"};function d(h,a,_,y,E,f){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="lucas-树" tabindex="-1">Lucas 树 <a class="header-anchor" href="#lucas-树" aria-label="Permalink to &quot;Lucas 树&quot;">​</a></h1><div class="epigraph"><p>果实外生落下，证券是对果实的要求权；价格使代表性主体愿意持有这棵树，随机折现因子就是果实的边际效用比。</p><footer>—— Lucas, Asset Prices in an Exchange Economy, Econometrica, 1978</footer></div><p><a href="/econ/state-price-sdf-bridge">上一课</a>焊好了 \\(q\\)、\\(m\\)、\\(\\mathbb{Q}\\)。本课缺口是<strong>均衡选取</strong>：在纯交换的禀赋经济里，消费等于树上落下的果实，\\(m\\) 不再是任意正核，而是 \\(\\beta u&#39;(y_{t+1})/u&#39;(y_t)\\)。不重写 FTAP，不把 Mehra–Prescott 的校准表提前铺开——谜是特化失败，树是装置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lucas（1978）：Markov 果实过程 \\(\\{y_t\\}\\)，代表性主体、完全市场、无生产。股权是对全部果实的要求权，债券是对确定支付的要求权。出清迫使 \\(c_t=y_t\\)，欧拉成为定价方程。价格是果实流在该核下的期望折现。缺口不是再定义 SDF，而是：无套利允许许多 \\(m\\)，出清加代表性主体选出一个，并且把选出的 \\(m\\) 绑在可观测的总量 \\(y\\) 上。</p><p>这与 <a href="/econ/capm-theory">CAPM</a> 的选取不同：CAPM 用均值方差加总把 \\(m\\) 绑在市场回报上；Lucas 树把 \\(m\\) 绑在禀赋边际效用上。两者都可以是完全市场均衡，坐标不同。CCAPM 是连续时间里把消费当充分统计；树是离散 Markov 的教室版。</p><p><span class="marginnote">Lucas, <em>Econometrica</em> 46(6), 1978。果实外生，故称交换经济。生产课序会让 \\(y\\) 对价格有反馈，那是 Cochrane 的生产基础定价，不是本课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bellman 或直接欧拉。股权价格 \\(p_t=p(y_t)\\) 满足</p> \\[p(y)=\\mathrm{E}\\Bigl[\\beta\\frac{u&#39;(y&#39;)}{u&#39;(y)}\\bigl(y&#39;+p(y&#39;)\\bigr)\\Bigm|y\\Bigr]. \\]<p>无风险利率由 \\(\\mathrm{E}[m\\mid y]\\) 的倒数给出。Markov 使价格是 \\(y\\) 的函数，不必另引泡沫项——横截条件把爆炸解关掉（理性泡沫课已从行为课序写过另一条缝）。本课默认基本面解。</p>',11)),(e(),c(m,null,{default:r(()=>[p(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%9E%9C%E5%AE%9E%20y%20%3D%20%E6%B6%88%E8%B4%B9%22%5D%20--%3E%20M%5B%22m%20%3D%20%CE%B2%20u'(y')%2Fu'(y)%22%5D%0A%20%20M%20--%3E%20P%5B%22p%20%3D%20E%5Bm%20(y'%2Bp')%5D%22%5D%0A%20%20P%20--%3E%20RF%5B%22Rf%20%3D%201%2FE%5Bm%5D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与信息课序：树通常假定公共信息，价格完全反映 \\(y\\) 的历史，没有 GS 采集。把果实做成私人观察，REE 与树可以叠，本课不叠，以免装置失焦。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是代表性主体必须愿意持有全部风险。没有外部，果实的波动就是消费波动，\\(u&#39;\\) 的波动就是 \\(m\\) 的波动。果实高的状态 \\(m\\) 低，股权在那时支付高，协方差为负，故有正溢价。债券在所有状态支付确定，溢价为零（实际债券），名义债券另论。股权溢价之谜已经在主干里：观测到的 \\(y\\) 太平，常规 \\(u\\) 给不出够抖的 \\(m\\)。本课只把机制钉在树上，不重跑校准。</p><p>生产一旦进来，\\(c\\) 可以平滑，\\(y\\) 不再等于 \\(c\\)，核跟着消费走而不是跟着股利走——后课生产基础会反过来用投资的一阶条件给回报定价。树是无平滑技术的对照。</p><p><span class="marginnote">异质主体、不完全市场会让 \\(m\\) 依赖某个加权消费或约束乘子，不再等于总量 \\(u&#39;(y)\\)。树是加总已经完成的特例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把树写成「股利贴现模型的实证」。后课 Campbell–Shiller 才把价格、股利、回报做成恒等式与预测。本课价格是均衡函数 \\(p(y)\\)，不是回归。也不要把树的 Markov 当成限价簿上的状态变量。</p><p>下一课：在不指定 \\(u\\) 的前提下，把价格、股利与回报的对数线性关系写成会计恒等式——Campbell–Shiller 分解。树给出的 \\(p(y)\\) 必须服从那条会计。</p><p>后课默认：交换经济出清 ⇒ \\(c=y\\) ⇒ \\(m\\) 由果实的边际效用给出。这是对 FTAP 集合的均衡选取，不是对 NA 的替代定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lucas 树：外生果实，出清 \\(c=y\\)，股权是对果实的要求权。</li><li>\\(m=\\beta u&#39;(y&#39;)/u&#39;(y)\\) 是均衡选出的核，价格是该核下的期望折现。</li><li>溢价之谜是这个特化在数据上抖不够，不是树的定义失败。</li><li>出处：Lucas, <em>Econometrica</em> 1978。</li></ul>',11))])}const A=s(u,[["render",d]]);export{P as __pageData,A as default};
